// Extrai metadados e conteúdo da mensagem da Meta Cloud API
const body = $json.body || $json;

if (!body.entry || !body.entry[0] || !body.entry[0].changes) {
  return [{ json: { isValid: false, reason: 'Payload sem entry' } }];
}

const change = body.entry[0].changes[0];
const value = change.value;

if (!value.messages || value.messages.length === 0) {
  // Evento de status de entrega ou echo
  if (value.message_echoes && value.message_echoes.length > 0) {
    return [{
      json: {
        isValid: true,
        type: 'ECHO',
        echo: value.message_echoes[0]
      }
    }];
  }
  return [{ json: { isValid: false, reason: 'Sem mensagens novas' } }];
}

const msg = value.messages[0];
const contact = (value.contacts && value.contacts[0]) || {};

let textContent = '';
let messageType = msg.type || 'text';
let mediaId = null;
let mimeType = null;

if (msg.type === 'text') {
  textContent = msg.text.body;
} else if (msg.type === 'image') {
  textContent = msg.image.caption || '[Foto de Lista / Peça Elétrica]';
  mediaId = msg.image.id;
  mimeType = msg.image.mime_type;
} else if (msg.type === 'audio' || msg.type === 'voice') {
  textContent = '[Áudio / Mensagem de Voz de Pedido]';
  mediaId = msg.audio ? msg.audio.id : (msg.voice ? msg.voice.id : null);
  mimeType = 'audio/ogg';
} else if (msg.type === 'document') {
  textContent = msg.document.caption || msg.document.filename || '[Documento de Pedido]';
  mediaId = msg.document.id;
  mimeType = msg.document.mime_type;
}

return [{
  json: {
    isValid: true,
    externalId: msg.id,
    senderPhone: msg.from,
    senderName: contact.profile ? contact.profile.name : `Cliente (${msg.from})`,
    messageType: messageType,
    textContent: textContent,
    mediaId: mediaId,
    mimeType: mimeType,
    timestamp: msg.timestamp,
    rawPayload: msg
  }
}];
